import React, { useState } from "react";
import './grid.css';
import Row from "./row";

interface GridProps {
    word: string;
    guessNumber: number;
}

const Grid: React.FC<GridProps> = ({word}) => {
    const [guesses, setGuess] = useState<string[]>(Array(6).fill('')); 
    const [guessNumber, addGuess] = useState(0);

    return(
        <>
            <div className="gridcontainer">
                <Row word = {guessNumber === 0 ? word : guesses[0]}/>
                <Row word = {guessNumber === 1 ? word : guesses[1]}/>
                <Row word = {guessNumber === 2 ? word : guesses[2]}/>
                <Row word = {guessNumber === 3 ? word : guesses[3]}/>
                <Row word = {guessNumber === 4 ? word : guesses[4]}/>
                <Row word = {guessNumber === 5 ? word : guesses[5]}/>
            </div>
        </>
    );
}

export default Grid;
